INSERT INTO memory_library (id, category, sort, reference, text) VALUES
 ('ml-salvation-01', 'salvation', 1, 'John 3:16', 'For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.'),
 ('ml-salvation-02', 'salvation', 2, 'Romans 3:23', 'For all have sinned, and come short of the glory of God;'),
 ('ml-salvation-03', 'salvation', 3, 'Romans 6:23', 'For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord.'),
 ('ml-salvation-04', 'salvation', 4, 'Ephesians 2:8-9', 'For by grace are ye saved through faith; and that not of yourselves: it is the gift of God: Not of works, lest any man should boast.'),
 ('ml-salvation-05', 'salvation', 5, 'Romans 5:8', 'But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.'),
 ('ml-salvation-06', 'salvation', 6, 'Romans 10:9-10', 'That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved. For with the heart man believeth unto righteousness; and with the mouth confession is made unto salvation.'),
 ('ml-salvation-07', 'salvation', 7, 'John 14:6', 'Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me.'),
 ('ml-salvation-08', 'salvation', 8, 'Acts 4:12', 'Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved.'),
 ('ml-salvation-09', 'salvation', 9, 'John 1:12', 'But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:'),
 ('ml-salvation-10', 'salvation', 10, 'Titus 3:5', 'Not by works of righteousness which we have done, but according to his mercy he saved us, by the washing of regeneration, and renewing of the Holy Ghost;'),
 ('ml-salvation-11', 'salvation', 11, '1 John 5:11-12', 'And this is the record, that God hath given to us eternal life, and this life is in his Son. He that hath the Son hath life; and he that hath not the Son of God hath not life.'),
 ('ml-salvation-12', 'salvation', 12, 'John 5:24', 'Verily, verily, I say unto you, He that heareth my word, and believeth on him that sent me, hath everlasting life, and shall not come into condemnation; but is passed from death unto life.'),
 ('ml-salvation-13', 'salvation', 13, 'Revelation 3:20', 'Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me.'),
 ('ml-salvation-14', 'salvation', 14, '1 Peter 3:18', 'For Christ also hath once suffered for sins, the just for the unjust, that he might bring us to God, being put to death in the flesh, but quickened by the Spirit:'),
 ('ml-faith-01', 'faith', 1, 'Hebrews 11:1', 'Now faith is the substance of things hoped for, the evidence of things not seen.'),
 ('ml-faith-02', 'faith', 2, 'Hebrews 11:6', 'But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him.'),
 ('ml-faith-03', 'faith', 3, 'Romans 10:17', 'So then faith cometh by hearing, and hearing by the word of God.'),
 ('ml-faith-04', 'faith', 4, '2 Corinthians 5:7', '(For we walk by faith, not by sight:)'),
 ('ml-faith-05', 'faith', 5, 'Matthew 17:20', 'And Jesus said unto them, Because of your unbelief: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove; and nothing shall be impossible unto you.'),
 ('ml-faith-06', 'faith', 6, 'Mark 9:23', 'Jesus said unto him, If thou canst believe, all things are possible to him that believeth.'),
 ('ml-faith-07', 'faith', 7, 'Hebrews 12:2', 'Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God.'),
 ('ml-faith-08', 'faith', 8, 'Romans 1:17', 'For therein is the righteousness of God revealed from faith to faith: as it is written, The just shall live by faith.'),
 ('ml-faith-09', 'faith', 9, 'James 1:6', 'But let him ask in faith, nothing wavering. For he that wavereth is like a wave of the sea driven with the wind and tossed.'),
 ('ml-faith-10', 'faith', 10, 'Ephesians 6:16', 'Above all, taking the shield of faith, wherewith ye shall be able to quench all the fiery darts of the wicked.'),
 ('ml-faith-11', 'faith', 11, '1 John 5:4', 'For whatsoever is born of God overcometh the world: and this is the victory that overcometh the world, even our faith.'),
 ('ml-faith-12', 'faith', 12, 'Romans 4:20-21', 'He staggered not at the promise of God through unbelief; but was strong in faith, giving glory to God; And being fully persuaded that, what he had promised, he was able also to perform.'),
 ('ml-faith-13', 'faith', 13, 'Habakkuk 2:4', 'Behold, his soul which is lifted up is not upright in him: but the just shall live by his faith.'),
 ('ml-faith-14', 'faith', 14, 'James 2:17', 'Even so faith, if it hath not works, is dead, being alone.'),
 ('ml-peace-01', 'peace', 1, 'Proverbs 3:5-6', 'Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths.'),
 ('ml-peace-02', 'peace', 2, 'Philippians 4:6-7', 'Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God. And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.'),
 ('ml-peace-03', 'peace', 3, 'John 14:27', 'Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.'),
 ('ml-peace-04', 'peace', 4, 'Isaiah 26:3', 'Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.'),
 ('ml-peace-05', 'peace', 5, 'Psalm 46:10', 'Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth.'),
 ('ml-peace-06', 'peace', 6, '1 Peter 5:7', 'Casting all your care upon him; for he careth for you.'),
 ('ml-peace-07', 'peace', 7, 'Matthew 11:28', 'Come unto me, all ye that labour and are heavy laden, and I will give you rest.'),
 ('ml-peace-08', 'peace', 8, 'John 16:33', 'These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.'),
 ('ml-peace-09', 'peace', 9, 'Psalm 4:8', 'I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety.'),
 ('ml-peace-10', 'peace', 10, 'Colossians 3:15', 'And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful.'),
 ('ml-peace-11', 'peace', 11, 'Psalm 37:5', 'Commit thy way unto the LORD; trust also in him; and he shall bring it to pass.'),
 ('ml-peace-12', 'peace', 12, 'Psalm 55:22', 'Cast thy burden upon the LORD, and he shall sustain thee: he shall never suffer the righteous to be moved.'),
 ('ml-peace-13', 'peace', 13, 'Psalm 91:1-2', 'He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty. I will say of the LORD, He is my refuge and my fortress: my God; in him will I trust.'),
 ('ml-peace-14', 'peace', 14, 'Psalm 29:11', 'The LORD will give strength unto his people; the LORD will bless his people with peace.'),
 ('ml-courage-01', 'courage', 1, 'Joshua 1:9', 'Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest.'),
 ('ml-courage-02', 'courage', 2, 'Isaiah 41:10', 'Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.'),
 ('ml-courage-03', 'courage', 3, '2 Timothy 1:7', 'For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.'),
 ('ml-courage-04', 'courage', 4, 'Psalm 27:1', 'The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?'),
 ('ml-courage-05', 'courage', 5, 'Deuteronomy 31:6', 'Be strong and of a good courage, fear not, nor be afraid of them: for the LORD thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee.'),
 ('ml-courage-06', 'courage', 6, 'Psalm 56:3', 'What time I am afraid, I will trust in thee.'),
 ('ml-courage-07', 'courage', 7, 'Psalm 23:4', 'Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.'),
 ('ml-courage-08', 'courage', 8, 'Romans 8:31', 'What shall we then say to these things? If God be for us, who can be against us?');
INSERT INTO memory_library (id, category, sort, reference, text) VALUES
 ('ml-courage-09', 'courage', 9, 'Psalm 118:6', 'The LORD is on my side; I will not fear: what can man do unto me?'),
 ('ml-courage-10', 'courage', 10, 'Isaiah 43:1', 'But now thus saith the LORD that created thee, O Jacob, and he that formed thee, O Israel, Fear not: for I have redeemed thee, I have called thee by thy name; thou art mine.'),
 ('ml-courage-11', 'courage', 11, 'Psalm 34:4', 'I sought the LORD, and he heard me, and delivered me from all my fears.'),
 ('ml-courage-12', 'courage', 12, 'Deuteronomy 31:8', 'And the LORD, he it is that doth go before thee; he will be with thee, he will not fail thee, neither forsake thee: fear not, neither be dismayed.'),
 ('ml-courage-13', 'courage', 13, 'Hebrews 13:6', 'So that we may boldly say, The Lord is my helper, and I will not fear what man shall do unto me.'),
 ('ml-courage-14', 'courage', 14, 'Psalm 112:7', 'He shall not be afraid of evil tidings: his heart is fixed, trusting in the LORD.'),
 ('ml-strength-01', 'strength', 1, 'Philippians 4:13', 'I can do all things through Christ which strengtheneth me.'),
 ('ml-strength-02', 'strength', 2, 'Isaiah 40:31', 'But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.'),
 ('ml-strength-03', 'strength', 3, 'Nehemiah 8:10', 'Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our LORD: neither be ye sorry; for the joy of the LORD is your strength.'),
 ('ml-strength-04', 'strength', 4, 'Psalm 46:1', 'God is our refuge and strength, a very present help in trouble.'),
 ('ml-strength-05', 'strength', 5, '2 Corinthians 12:9', 'And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me.'),
 ('ml-strength-06', 'strength', 6, 'Psalm 73:26', 'My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever.'),
 ('ml-strength-07', 'strength', 7, 'Isaiah 40:29', 'He giveth power to the faint; and to them that have no might he increaseth strength.'),
 ('ml-strength-08', 'strength', 8, 'Ephesians 6:10', 'Finally, my brethren, be strong in the Lord, and in the power of his might.'),
 ('ml-strength-09', 'strength', 9, 'Psalm 28:7', 'The LORD is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoiceth; and with my song will I praise him.'),
 ('ml-strength-10', 'strength', 10, 'Psalm 18:2', 'The LORD is my rock, and my fortress, and my deliverer; my God, my strength, in whom I will trust; my buckler, and the horn of my salvation, and my high tower.'),
 ('ml-strength-11', 'strength', 11, 'Habakkuk 3:19', 'The LORD God is my strength, and he will make my feet like hinds'' feet, and he will make me to walk upon mine high places. To the chief singer on my stringed instruments.'),
 ('ml-strength-12', 'strength', 12, 'Exodus 15:2', 'The LORD is my strength and song, and he is become my salvation: he is my God, and I will prepare him an habitation; my father''s God, and I will exalt him.'),
 ('ml-strength-13', 'strength', 13, 'Psalm 138:3', 'In the day when I cried thou answeredst me, and strengthenedst me with strength in my soul.'),
 ('ml-strength-14', 'strength', 14, 'Psalm 18:32', 'It is God that girdeth me with strength, and maketh my way perfect.'),
 ('ml-love-01', 'love', 1, 'John 13:34-35', 'A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another. By this shall all men know that ye are my disciples, if ye have love one to another.'),
 ('ml-love-02', 'love', 2, '1 Corinthians 13:4-5', 'Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up, Doth not behave itself unseemly, seeketh not her own, is not easily provoked, thinketh no evil;'),
 ('ml-love-03', 'love', 3, '1 John 4:19', 'We love him, because he first loved us.'),
 ('ml-love-04', 'love', 4, '1 John 4:8', 'He that loveth not knoweth not God; for God is love.'),
 ('ml-love-05', 'love', 5, 'Romans 8:38-39', 'For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come, Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord.'),
 ('ml-love-06', 'love', 6, 'John 15:13', 'Greater love hath no man than this, that a man lay down his life for his friends.'),
 ('ml-love-07', 'love', 7, '1 Corinthians 13:13', 'And now abideth faith, hope, charity, these three; but the greatest of these is charity.'),
 ('ml-love-08', 'love', 8, '1 John 4:7', 'Beloved, let us love one another: for love is of God; and every one that loveth is born of God, and knoweth God.'),
 ('ml-love-09', 'love', 9, 'Matthew 22:37', 'Jesus said unto him, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind.'),
 ('ml-love-10', 'love', 10, '1 Peter 4:8', 'And above all things have fervent charity among yourselves: for charity shall cover the multitude of sins.'),
 ('ml-love-11', 'love', 11, 'Jeremiah 31:3', 'The LORD hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.'),
 ('ml-love-12', 'love', 12, 'Romans 13:10', 'Love worketh no ill to his neighbour: therefore love is the fulfilling of the law.'),
 ('ml-love-13', 'love', 13, '1 John 3:18', 'My little children, let us not love in word, neither in tongue; but in deed and in truth.'),
 ('ml-love-14', 'love', 14, 'Zephaniah 3:17', 'The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing.'),
 ('ml-prayer-01', 'prayer', 1, 'Matthew 7:7', 'Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:'),
 ('ml-prayer-02', 'prayer', 2, '1 Thessalonians 5:17', 'Pray without ceasing.'),
 ('ml-prayer-03', 'prayer', 3, 'Jeremiah 33:3', 'Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not.'),
 ('ml-prayer-04', 'prayer', 4, 'Mark 11:24', 'Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them.'),
 ('ml-prayer-05', 'prayer', 5, 'James 5:16', 'Confess your faults one to another, and pray one for another, that ye may be healed. The effectual fervent prayer of a righteous man availeth much.'),
 ('ml-prayer-06', 'prayer', 6, '1 John 5:14-15', 'And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us: And if we know that he hear us, whatsoever we ask, we know that we have the petitions that we desired of him.'),
 ('ml-prayer-07', 'prayer', 7, 'John 15:7', 'If ye abide in me, and my words abide in you, ye shall ask what ye will, and it shall be done unto you.'),
 ('ml-prayer-08', 'prayer', 8, 'Matthew 6:6', 'But thou, when thou prayest, enter into thy closet, and when thou hast shut thy door, pray to thy Father which is in secret; and thy Father which seeth in secret shall reward thee openly.'),
 ('ml-prayer-09', 'prayer', 9, 'Matthew 18:20', 'For where two or three are gathered together in my name, there am I in the midst of them.'),
 ('ml-prayer-10', 'prayer', 10, 'John 14:13-14', 'And whatsoever ye shall ask in my name, that will I do, that the Father may be glorified in the Son. If ye shall ask any thing in my name, I will do it.'),
 ('ml-prayer-11', 'prayer', 11, 'Hebrews 4:16', 'Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need.'),
 ('ml-prayer-12', 'prayer', 12, 'Psalm 145:18', 'The LORD is nigh unto all them that call upon him, to all that call upon him in truth.'),
 ('ml-prayer-13', 'prayer', 13, '2 Chronicles 7:14', 'If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land.'),
 ('ml-prayer-14', 'prayer', 14, 'Psalm 5:3', 'My voice shalt thou hear in the morning, O LORD; in the morning will I direct my prayer unto thee, and will look up.'),
 ('ml-word-01', 'word', 1, 'Psalm 119:105', 'Thy word is a lamp unto my feet, and a light unto my path.'),
 ('ml-word-02', 'word', 2, 'Psalm 119:11', 'Thy word have I hid in mine heart, that I might not sin against thee.');
INSERT INTO memory_library (id, category, sort, reference, text) VALUES
 ('ml-word-03', 'word', 3, '2 Timothy 3:16-17', 'All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness: That the man of God may be perfect, throughly furnished unto all good works.'),
 ('ml-word-04', 'word', 4, 'Hebrews 4:12', 'For the word of God is quick, and powerful, and sharper than any twoedged sword, piercing even to the dividing asunder of soul and spirit, and of the joints and marrow, and is a discerner of the thoughts and intents of the heart.'),
 ('ml-word-05', 'word', 5, 'Joshua 1:8', 'This book of the law shall not depart out of thy mouth; but thou shalt meditate therein day and night, that thou mayest observe to do according to all that is written therein: for then thou shalt make thy way prosperous, and then thou shalt have good success.'),
 ('ml-word-06', 'word', 6, 'Matthew 4:4', 'But he answered and said, It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God.'),
 ('ml-word-07', 'word', 7, 'Isaiah 40:8', 'The grass withereth, the flower fadeth: but the word of our God shall stand for ever.'),
 ('ml-word-08', 'word', 8, 'James 1:22', 'But be ye doers of the word, and not hearers only, deceiving your own selves.'),
 ('ml-word-09', 'word', 9, 'Matthew 24:35', 'Heaven and earth shall pass away, but my words shall not pass away.'),
 ('ml-word-10', 'word', 10, 'Psalm 1:1-2', 'Blessed is the man that walketh not in the counsel of the ungodly, nor standeth in the way of sinners, nor sitteth in the seat of the scornful. But his delight is in the law of the LORD; and in his law doth he meditate day and night.'),
 ('ml-word-11', 'word', 11, 'John 17:17', 'Sanctify them through thy truth: thy word is truth.'),
 ('ml-word-12', 'word', 12, '2 Timothy 2:15', 'Study to shew thyself approved unto God, a workman that needeth not to be ashamed, rightly dividing the word of truth.'),
 ('ml-word-13', 'word', 13, 'Romans 15:4', 'For whatsoever things were written aforetime were written for our learning, that we through patience and comfort of the scriptures might have hope.'),
 ('ml-word-14', 'word', 14, 'Psalm 119:9', 'Wherewithal shall a young man cleanse his way? by taking heed thereto according to thy word.'),
 ('ml-spirit-01', 'spirit', 1, 'Acts 1:8', 'But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth.'),
 ('ml-spirit-02', 'spirit', 2, 'Galatians 5:22-23', 'But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, Meekness, temperance: against such there is no law.'),
 ('ml-spirit-03', 'spirit', 3, 'John 14:26', 'But the Comforter, which is the Holy Ghost, whom the Father will send in my name, he shall teach you all things, and bring all things to your remembrance, whatsoever I have said unto you.'),
 ('ml-spirit-04', 'spirit', 4, 'Romans 8:26', 'Likewise the Spirit also helpeth our infirmities: for we know not what we should pray for as we ought: but the Spirit itself maketh intercession for us with groanings which cannot be uttered.'),
 ('ml-spirit-05', 'spirit', 5, 'John 16:13', 'Howbeit when he, the Spirit of truth, is come, he will guide you into all truth: for he shall not speak of himself; but whatsoever he shall hear, that shall he speak: and he will shew you things to come.'),
 ('ml-spirit-06', 'spirit', 6, '1 Corinthians 6:19', 'What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?'),
 ('ml-spirit-07', 'spirit', 7, 'Zechariah 4:6', 'Then he answered and spake unto me, saying, This is the word of the LORD unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the LORD of hosts.'),
 ('ml-spirit-08', 'spirit', 8, 'Galatians 5:16', 'This I say then, Walk in the Spirit, and ye shall not fulfil the lust of the flesh.'),
 ('ml-spirit-09', 'spirit', 9, 'Romans 8:14', 'For as many as are led by the Spirit of God, they are the sons of God.'),
 ('ml-spirit-10', 'spirit', 10, 'Luke 11:13', 'If ye then, being evil, know how to give good gifts unto your children: how much more shall your heavenly Father give the Holy Spirit to them that ask him?'),
 ('ml-spirit-11', 'spirit', 11, 'Ephesians 5:18', 'And be not drunk with wine, wherein is excess; but be filled with the Spirit;'),
 ('ml-spirit-12', 'spirit', 12, 'Ephesians 4:30', 'And grieve not the holy Spirit of God, whereby ye are sealed unto the day of redemption.'),
 ('ml-spirit-13', 'spirit', 13, 'Romans 8:16', 'The Spirit itself beareth witness with our spirit, that we are the children of God:'),
 ('ml-spirit-14', 'spirit', 14, '2 Corinthians 3:17', 'Now the Lord is that Spirit: and where the Spirit of the Lord is, there is liberty.'),
 ('ml-guidance-01', 'guidance', 1, 'James 1:5', 'If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.'),
 ('ml-guidance-02', 'guidance', 2, 'Psalm 32:8', 'I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye.'),
 ('ml-guidance-03', 'guidance', 3, 'Proverbs 16:9', 'A man''s heart deviseth his way: but the LORD directeth his steps.'),
 ('ml-guidance-04', 'guidance', 4, 'Isaiah 30:21', 'And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left.'),
 ('ml-guidance-05', 'guidance', 5, 'Proverbs 1:7', 'The fear of the LORD is the beginning of knowledge: but fools despise wisdom and instruction.'),
 ('ml-guidance-06', 'guidance', 6, 'Proverbs 16:3', 'Commit thy works unto the LORD, and thy thoughts shall be established.'),
 ('ml-guidance-07', 'guidance', 7, 'Psalm 37:23', 'The steps of a good man are ordered by the LORD: and he delighteth in his way.'),
 ('ml-guidance-08', 'guidance', 8, 'Proverbs 9:10', 'The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.'),
 ('ml-guidance-09', 'guidance', 9, 'Psalm 25:4-5', 'Shew me thy ways, O LORD; teach me thy paths. Lead me in thy truth, and teach me: for thou art the God of my salvation; on thee do I wait all the day.'),
 ('ml-guidance-10', 'guidance', 10, 'Proverbs 2:6', 'For the LORD giveth wisdom: out of his mouth cometh knowledge and understanding.'),
 ('ml-guidance-11', 'guidance', 11, 'Isaiah 58:11', 'And the LORD shall guide thee continually, and satisfy thy soul in drought, and make fat thy bones: and thou shalt be like a watered garden, and like a spring of water, whose waters fail not.'),
 ('ml-guidance-12', 'guidance', 12, 'James 3:17', 'But the wisdom that is from above is first pure, then peaceable, gentle, and easy to be intreated, full of mercy and good fruits, without partiality, and without hypocrisy.'),
 ('ml-guidance-13', 'guidance', 13, 'Psalm 143:8', 'Cause me to hear thy lovingkindness in the morning; for in thee do I trust: cause me to know the way wherein I should walk; for I lift up my soul unto thee.'),
 ('ml-guidance-14', 'guidance', 14, 'Psalm 48:14', 'For this God is our God for ever and ever: he will be our guide even unto death.'),
 ('ml-hope-01', 'hope', 1, 'Jeremiah 29:11', 'For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end.'),
 ('ml-hope-02', 'hope', 2, 'Romans 8:28', 'And we know that all things work together for good to them that love God, to them who are the called according to his purpose.'),
 ('ml-hope-03', 'hope', 3, 'Romans 15:13', 'Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost.'),
 ('ml-hope-04', 'hope', 4, 'Revelation 21:4', 'And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.'),
 ('ml-hope-05', 'hope', 5, 'Psalm 34:18', 'The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.'),
 ('ml-hope-06', 'hope', 6, 'Lamentations 3:22-23', 'It is of the LORD''s mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness.'),
 ('ml-hope-07', 'hope', 7, 'Matthew 5:4', 'Blessed are they that mourn: for they shall be comforted.'),
 ('ml-hope-08', 'hope', 8, 'Psalm 147:3', 'He healeth the broken in heart, and bindeth up their wounds.'),
 ('ml-hope-09', 'hope', 9, 'John 14:1', 'Let not your heart be troubled: ye believe in God, believe also in me.'),
 ('ml-hope-10', 'hope', 10, 'Romans 8:18', 'For I reckon that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us.');
INSERT INTO memory_library (id, category, sort, reference, text) VALUES
 ('ml-hope-11', 'hope', 11, '2 Corinthians 4:17', 'For our light affliction, which is but for a moment, worketh for us a far more exceeding and eternal weight of glory;'),
 ('ml-hope-12', 'hope', 12, 'Psalm 30:5', 'For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.'),
 ('ml-hope-13', 'hope', 13, 'Hebrews 6:19', 'Which hope we have as an anchor of the soul, both sure and stedfast, and which entereth into that within the veil;'),
 ('ml-hope-14', 'hope', 14, 'Psalm 71:5', 'For thou art my hope, O Lord GOD: thou art my trust from my youth.'),
 ('ml-provision-01', 'provision', 1, 'Philippians 4:19', 'But my God shall supply all your need according to his riches in glory by Christ Jesus.'),
 ('ml-provision-02', 'provision', 2, 'Psalm 23:1', 'The LORD is my shepherd; I shall not want.'),
 ('ml-provision-03', 'provision', 3, 'Matthew 6:33', 'But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.'),
 ('ml-provision-04', 'provision', 4, 'Matthew 6:26', 'Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?'),
 ('ml-provision-05', 'provision', 5, 'Psalm 37:4', 'Delight thyself also in the LORD: and he shall give thee the desires of thine heart.'),
 ('ml-provision-06', 'provision', 6, 'Psalm 37:25', 'I have been young, and now am old; yet have I not seen the righteous forsaken, nor his seed begging bread.'),
 ('ml-provision-07', 'provision', 7, 'Psalm 34:10', 'The young lions do lack, and suffer hunger: but they that seek the LORD shall not want any good thing.'),
 ('ml-provision-08', 'provision', 8, 'Hebrews 13:5', 'Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.'),
 ('ml-provision-09', 'provision', 9, 'Psalm 121:1-2', 'I will lift up mine eyes unto the hills, from whence cometh my help. My help cometh from the LORD, which made heaven and earth.'),
 ('ml-provision-10', 'provision', 10, '2 Corinthians 9:8', 'And God is able to make all grace abound toward you; that ye, always having all sufficiency in all things, may abound to every good work:'),
 ('ml-provision-11', 'provision', 11, 'Psalm 84:11', 'For the LORD God is a sun and shield: the LORD will give grace and glory: no good thing will he withhold from them that walk uprightly.'),
 ('ml-provision-12', 'provision', 12, 'James 1:17', 'Every good gift and every perfect gift is from above, and cometh down from the Father of lights, with whom is no variableness, neither shadow of turning.'),
 ('ml-provision-13', 'provision', 13, 'Matthew 7:11', 'If ye then, being evil, know how to give good gifts unto your children, how much more shall your Father which is in heaven give good things to them that ask him?'),
 ('ml-provision-14', 'provision', 14, 'Psalm 145:15-16', 'The eyes of all wait upon thee; and thou givest them their meat in due season. Thou openest thine hand, and satisfiest the desire of every living thing.'),
 ('ml-forgiveness-01', 'forgiveness', 1, '1 John 1:9', 'If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness.'),
 ('ml-forgiveness-02', 'forgiveness', 2, 'Ephesians 4:32', 'And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ''s sake hath forgiven you.'),
 ('ml-forgiveness-03', 'forgiveness', 3, 'Psalm 103:12', 'As far as the east is from the west, so far hath he removed our transgressions from us.'),
 ('ml-forgiveness-04', 'forgiveness', 4, 'Colossians 3:13', 'Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye.'),
 ('ml-forgiveness-05', 'forgiveness', 5, 'Matthew 6:14-15', 'For if ye forgive men their trespasses, your heavenly Father will also forgive you: But if ye forgive not men their trespasses, neither will your Father forgive your trespasses.'),
 ('ml-forgiveness-06', 'forgiveness', 6, 'Isaiah 1:18', 'Come now, and let us reason together, saith the LORD: though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool.'),
 ('ml-forgiveness-07', 'forgiveness', 7, 'Acts 3:19', 'Repent ye therefore, and be converted, that your sins may be blotted out, when the times of refreshing shall come from the presence of the Lord;'),
 ('ml-forgiveness-08', 'forgiveness', 8, 'Proverbs 28:13', 'He that covereth his sins shall not prosper: but whoso confesseth and forsaketh them shall have mercy.'),
 ('ml-forgiveness-09', 'forgiveness', 9, 'Psalm 32:5', 'I acknowledged my sin unto thee, and mine iniquity have I not hid. I said, I will confess my transgressions unto the LORD; and thou forgavest the iniquity of my sin. Selah.'),
 ('ml-forgiveness-10', 'forgiveness', 10, 'Isaiah 43:25', 'I, even I, am he that blotteth out thy transgressions for mine own sake, and will not remember thy sins.'),
 ('ml-forgiveness-11', 'forgiveness', 11, 'Mark 11:25', 'And when ye stand praying, forgive, if ye have ought against any: that your Father also which is in heaven may forgive you your trespasses.'),
 ('ml-forgiveness-12', 'forgiveness', 12, 'Ephesians 1:7', 'In whom we have redemption through his blood, the forgiveness of sins, according to the riches of his grace;'),
 ('ml-forgiveness-13', 'forgiveness', 13, 'Psalm 86:5', 'For thou, Lord, art good, and ready to forgive; and plenteous in mercy unto all them that call upon thee.'),
 ('ml-forgiveness-14', 'forgiveness', 14, 'Micah 7:18', 'Who is a God like unto thee, that pardoneth iniquity, and passeth by the transgression of the remnant of his heritage? he retaineth not his anger for ever, because he delighteth in mercy.'),
 ('ml-identity-01', 'identity', 1, '2 Corinthians 5:17', 'Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new.'),
 ('ml-identity-02', 'identity', 2, 'Galatians 2:20', 'I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me.'),
 ('ml-identity-03', 'identity', 3, 'Romans 8:1', 'There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit.'),
 ('ml-identity-04', 'identity', 4, 'Ephesians 2:10', 'For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them.'),
 ('ml-identity-05', 'identity', 5, '1 Peter 2:9', 'But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light:'),
 ('ml-identity-06', 'identity', 6, 'Psalm 139:14', 'I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well.'),
 ('ml-identity-07', 'identity', 7, '1 John 3:1', 'Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not.'),
 ('ml-identity-08', 'identity', 8, 'Romans 8:37', 'Nay, in all these things we are more than conquerors through him that loved us.'),
 ('ml-identity-09', 'identity', 9, 'John 15:5', 'I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing.'),
 ('ml-identity-10', 'identity', 10, 'Matthew 5:14', 'Ye are the light of the world. A city that is set on an hill cannot be hid.'),
 ('ml-identity-11', 'identity', 11, 'Philippians 1:6', 'Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:'),
 ('ml-identity-12', 'identity', 12, '2 Corinthians 5:21', 'For he hath made him to be sin for us, who knew no sin; that we might be made the righteousness of God in him.'),
 ('ml-identity-13', 'identity', 13, 'Galatians 3:26', 'For ye are all the children of God by faith in Christ Jesus.'),
 ('ml-identity-14', 'identity', 14, 'Colossians 3:3', 'For ye are dead, and your life is hid with Christ in God.'),
 ('ml-praise-01', 'praise', 1, 'Psalm 118:24', 'This is the day which the LORD hath made; we will rejoice and be glad in it.'),
 ('ml-praise-02', 'praise', 2, '1 Thessalonians 5:18', 'In every thing give thanks: for this is the will of God in Christ Jesus concerning you.'),
 ('ml-praise-03', 'praise', 3, 'Psalm 100:4', 'Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name.'),
 ('ml-praise-04', 'praise', 4, 'Psalm 150:6', 'Let every thing that hath breath praise the LORD. Praise ye the LORD.');
INSERT INTO memory_library (id, category, sort, reference, text) VALUES
 ('ml-praise-05', 'praise', 5, 'Psalm 103:1-2', 'Bless the LORD, O my soul: and all that is within me, bless his holy name. Bless the LORD, O my soul, and forget not all his benefits:'),
 ('ml-praise-06', 'praise', 6, 'Psalm 34:1', 'I will bless the LORD at all times: his praise shall continually be in my mouth.'),
 ('ml-praise-07', 'praise', 7, 'Psalm 107:1', 'O give thanks unto the LORD, for he is good: for his mercy endureth for ever.'),
 ('ml-praise-08', 'praise', 8, 'Hebrews 13:15', 'By him therefore let us offer the sacrifice of praise to God continually, that is, the fruit of our lips giving thanks to his name.'),
 ('ml-praise-09', 'praise', 9, 'Colossians 3:17', 'And whatsoever ye do in word or deed, do all in the name of the Lord Jesus, giving thanks to God and the Father by him.'),
 ('ml-praise-10', 'praise', 10, 'Psalm 9:1', 'I will praise thee, O LORD, with my whole heart; I will shew forth all thy marvellous works.'),
 ('ml-praise-11', 'praise', 11, 'Psalm 63:3', 'Because thy lovingkindness is better than life, my lips shall praise thee.'),
 ('ml-praise-12', 'praise', 12, 'Psalm 95:1', 'O come, let us sing unto the LORD: let us make a joyful noise to the rock of our salvation.'),
 ('ml-praise-13', 'praise', 13, 'Ephesians 5:20', 'Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;'),
 ('ml-praise-14', 'praise', 14, 'Psalm 145:3', 'Great is the LORD, and greatly to be praised; and his greatness is unsearchable.'),
 ('ml-holiness-01', 'holiness', 1, 'Romans 12:2', 'And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.'),
 ('ml-holiness-02', 'holiness', 2, 'John 14:15', 'If ye love me, keep my commandments.'),
 ('ml-holiness-03', 'holiness', 3, '1 Corinthians 10:13', 'There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it.'),
 ('ml-holiness-04', 'holiness', 4, 'Micah 6:8', 'He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?'),
 ('ml-holiness-05', 'holiness', 5, 'Psalm 51:10', 'Create in me a clean heart, O God; and renew a right spirit within me.'),
 ('ml-holiness-06', 'holiness', 6, '1 Peter 1:15-16', 'But as he which hath called you is holy, so be ye holy in all manner of conversation; Because it is written, Be ye holy; for I am holy.'),
 ('ml-holiness-07', 'holiness', 7, 'James 4:7', 'Submit yourselves therefore to God. Resist the devil, and he will flee from you.'),
 ('ml-holiness-08', 'holiness', 8, 'Romans 12:1', 'I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service.'),
 ('ml-holiness-09', 'holiness', 9, 'Proverbs 4:23', 'Keep thy heart with all diligence; for out of it are the issues of life.'),
 ('ml-holiness-10', 'holiness', 10, 'Matthew 5:16', 'Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.'),
 ('ml-holiness-11', 'holiness', 11, 'Colossians 3:23', 'And whatsoever ye do, do it heartily, as to the Lord, and not unto men;'),
 ('ml-holiness-12', 'holiness', 12, 'Matthew 16:24', 'Then said Jesus unto his disciples, If any man will come after me, let him deny himself, and take up his cross, and follow me.'),
 ('ml-holiness-13', 'holiness', 13, 'Hebrews 12:14', 'Follow peace with all men, and holiness, without which no man shall see the Lord:'),
 ('ml-holiness-14', 'holiness', 14, '2 Timothy 2:22', 'Flee also youthful lusts: but follow righteousness, faith, charity, peace, with them that call on the Lord out of a pure heart.');
INSERT INTO prayer_library (id, category, sort, title, prayer, reference) VALUES
 ('pl-family-01', 'family', 1, 'For my marriage', 'Father, thank You for the gift of my spouse. Teach us to be humble, gentle and patient with each other, bearing with one another in love. Guard the unity and peace of our home, and let our marriage point others to You. In Jesus’ name, Amen.', 'Ephesians 4:2-3'),
 ('pl-family-02', 'family', 2, 'For my children', 'Lord, I place my children in Your hands. Teach them Your ways Yourself, and let great peace rest on their hearts and minds. Draw each one close to You, guard their friendships and choices, and help me love them the way You love me. In Jesus’ name, Amen.', 'Isaiah 54:13'),
 ('pl-family-03', 'family', 3, 'For my parents', 'Father, thank You for my parents and all they have poured into my life. Help me honour them with my words, my time and my care. Bless them with good health, peace of mind and a close walk with You in every season of life. In Jesus’ name, Amen.', 'Exodus 20:12'),
 ('pl-family-04', 'family', 4, 'Waiting on God', 'Lord, while I wait, I choose to delight in You first. I commit my desire for a godly spouse into Your hands and trust Your timing. Keep my heart pure, content and full of purpose in this season, and lead me to the right person in Your way. In Jesus’ name, Amen.', 'Psalm 37:4-5'),
 ('pl-family-05', 'family', 5, 'Peace at home', 'Prince of Peace, let Your peace rule in our home. Calm our tempers, soften our words and help us forgive quickly. Fill our house with gratitude instead of complaint, so that everyone who lives here or visits feels Your rest. In Jesus’ name, Amen.', 'Colossians 3:15'),
 ('pl-family-06', 'family', 6, 'For my family’s salvation', 'Lord Jesus, I believe Your promise that salvation can reach my whole household. I lift up every family member who does not yet know You. Open their eyes to Your love, send the right people across their path and help my life show them who You are. In Jesus’ name, Amen.', 'Acts 16:31'),
 ('pl-family-07', 'family', 7, 'Protection over us', 'Father, You are the keeper of my family. Preserve us from all evil, and watch over our going out and coming in, on the roads, at school, at work and at home. When we lie down, let us rest knowing You never sleep. In Jesus’ name, Amen.', 'Psalm 121:7-8'),
 ('pl-family-08', 'family', 8, 'Wisdom as a parent', 'Lord, parenting stretches me beyond what I know. You promised to give wisdom generously to anyone who asks, so I ask today. Show me when to correct and when to comfort, when to speak and when to listen, and help me raise my children with grace. In Jesus’ name, Amen.', 'James 1:5'),
 ('pl-family-09', 'family', 9, 'Healing family rifts', 'Father, You know the hurt and distance in my family. As Christ forgave me, help me forgive those who wounded me and humbly seek forgiveness where I was wrong. Heal old wounds, soften hard hearts and restore what seems broken beyond repair. In Jesus’ name, Amen.', 'Colossians 3:13'),
 ('pl-family-10', 'family', 10, 'For my extended family', 'Lord, thank You for my aunts, uncles, cousins, in-laws and grandparents. I remember each of them before You with joy. Meet their needs, strengthen their bodies and their faith, and bind our wider family together in love and kindness. In Jesus’ name, Amen.', 'Philippians 1:3-4'),
 ('pl-family-11', 'family', 11, 'A home of prayer', 'Father, as for me and my house, we will serve You. Make our home a place of prayer, where Your Word is read, worship is sung and problems are brought to You first. Help us build habits of faith our children will carry for life. In Jesus’ name, Amen.', 'Joshua 24:15'),
 ('pl-family-12', 'family', 12, 'Generations to come', 'Lord, I pray for the generations that will come after me. Help us tell our children and grandchildren of Your praises, Your strength and Your wonderful works. Let faith, not fear or bitterness, be the inheritance we pass on. In Jesus’ name, Amen.', 'Psalm 78:4'),
 ('pl-church-01', 'church', 1, 'For our pastors', 'Father, thank You for giving us pastors after Your own heart. Strengthen our leaders as they feed us with knowledge and understanding. Protect their families, renew them when they are weary and keep them humble and close to You. Help us honour and support them well. In Jesus’ name, Amen.', 'Jeremiah 3:15'),
 ('pl-church-02', 'church', 2, 'Unity in the church', 'Lord, how good and pleasant it is when Your people dwell together in unity. Heal divisions in our church, silence gossip and help us value one another above ourselves. Make us one family, united around Jesus and His mission. In Jesus’ name, Amen.', 'Psalm 133:1'),
 ('pl-church-03', 'church', 3, 'Worship in spirit', 'Father, You are seeking people who will worship You in spirit and in truth. Let our worship be more than songs; let it be hearts fully surrendered to You. Anoint our musicians and singers, and fill our gatherings with Your presence. In Jesus’ name, Amen.', 'John 4:23-24'),
 ('pl-church-04', 'church', 4, 'For our youth', 'Lord, I lift up the young people in our church. Let no one despise their youth; make them examples in word, conduct, love, faith and purity. Protect them from harmful influences, give them godly friends and set their hearts on fire for You. In Jesus’ name, Amen.', '1 Timothy 4:12'),
 ('pl-church-05', 'church', 5, 'Children’s ministry', 'Lord Jesus, You welcomed little children and blessed them. Bless our children’s ministry and every teacher who serves there. Give them patience, creativity and love, and let every child who walks through our doors know how much You love them. In Jesus’ name, Amen.', 'Mark 10:14'),
 ('pl-church-06', 'church', 6, 'For new believers', 'Father, thank You for everyone who has recently given their life to Jesus. Complete the good work You have begun in them. Root them in Your Word, surround them with caring believers and help them grow strong when doubts or trials come. In Jesus’ name, Amen.', 'Philippians 1:6'),
 ('pl-church-07', 'church', 7, 'The lost in our city', 'Lord of the harvest, the harvest in our city is plentiful, and many around us are searching and hurting. Send labourers into Your harvest, starting with me. Give our church courage and compassion to share the good news in our streets, markets, offices and homes. In Jesus’ name, Amen.', 'Matthew 9:37-38'),
 ('pl-church-08', 'church', 8, 'Workers and volunteers', 'Father, bless every usher, cleaner, technician, teacher and volunteer who serves in our church. When they feel unseen or tired, keep them from growing weary in well doing. Remind them that in due season they will reap, and reward their faithfulness. In Jesus’ name, Amen.', 'Galatians 6:9'),
 ('pl-church-09', 'church', 9, 'Growth in the Word', 'Lord, let the word of Christ dwell richly in our church. Give us hunger for the Scriptures, teachers who handle them faithfully and hearts that obey what we read. Let Your Word shape our conversations, our worship and our daily decisions. In Jesus’ name, Amen.', 'Colossians 3:16'),
 ('pl-church-10', 'church', 10, 'For revival', 'O Lord, revive Your work in our day. Where our love has grown cold, set it on fire again. Pour out Your Spirit on our church, draw us to repentance and prayer, and let a fresh move of Your presence spill out into our community. In Jesus’ name, Amen.', 'Habakkuk 3:2'),
 ('pl-church-11', 'church', 11, 'The sick among us', 'Father, I lift up every sick member of our church family. You hear the prayer of faith and You raise up the sick. Bring healing, relieve pain, guide doctors and surround each one with comfort and practical care from Your people. In Jesus’ name, Amen.', 'James 5:15'),
 ('pl-church-12', 'church', 12, 'For missions', 'Lord, You have called us to be Your witnesses to the ends of the earth. Strengthen the missionaries we pray for with health, protection and joy. Fill them with the Holy Spirit’s power, open doors for the gospel and show each of us our part in Your mission. In Jesus’ name, Amen.', 'Acts 1:8'),
 ('pl-career-01', 'career', 1, 'For a new job', 'Father, I am looking for new work, and I trust You to guide me. Instruct me and teach me the way I should go. Open the right doors, close the wrong ones, and give me confidence in interviews and peace while I wait. In Jesus’ name, Amen.', 'Psalm 32:8'),
 ('pl-career-02', 'career', 2, 'Favour at work', 'Lord, let mercy and truth mark the way I work. As I walk in kindness and honesty, give me favour and good understanding with You and with the people I work alongside. Let my attitude open doors that talent alone cannot. In Jesus’ name, Amen.', 'Proverbs 3:3-4'),
 ('pl-career-03', 'career', 3, 'Excellence and integrity', 'Father, help me do my work heartily, as for You and not just for people. Whether anyone is watching or not, let me be diligent, honest and excellent. Keep me from cutting corners, and let my work quietly reflect Your goodness. In Jesus’ name, Amen.', 'Colossians 3:23'),
 ('pl-career-04', 'career', 4, 'A difficult boss', 'Lord, You see how hard it is to work under my boss. As much as depends on me, help me live at peace. Guard my tongue, give me wisdom to respond calmly and courage to speak up when needed. Soften their heart, and bless them. In Jesus’ name, Amen.', 'Romans 12:18'),
 ('pl-career-05', 'career', 5, 'Students and exams', 'Father, as You gave Daniel and his friends knowledge and skill in learning, grant me understanding as I study. Help me focus, remember what I have learned and stay calm in the exam hall. Keep me honest, and let my results bring You glory. In Jesus’ name, Amen.', 'Daniel 1:17'),
 ('pl-career-06', 'career', 6, 'For business owners', 'Lord, let Your beauty rest on us and establish the work of our hands. Give business owners wisdom with customers, staff and suppliers, and help us trade honestly. Protect small businesses in hard times, and let our work serve our communities well. In Jesus’ name, Amen.', 'Psalm 90:17'),
 ('pl-career-07', 'career', 7, 'Wise decisions', 'Father, I have a decision to make, and I do not want to lean on my own understanding. I trust You with all my heart and acknowledge You in this choice. Direct my path, send godly counsel and let Your peace confirm the way forward. In Jesus’ name, Amen.', 'Proverbs 3:5-6'),
 ('pl-career-08', 'career', 8, 'Rest from overwork', 'Lord Jesus, I am tired, and my work has taken more than it should. You invited the weary to come to You, so I come. Give me rest for my body and soul, help me set healthy limits and remind me my worth is not measured by my output. In Jesus’ name, Amen.', 'Matthew 11:28'),
 ('pl-career-09', 'career', 9, 'For the unemployed', 'Father, I lift up everyone who is out of work and searching. When fear and discouragement rise, remind them You are with them and will strengthen and help them. Open doors of employment, send practical support and let them feel valued while they wait. In Jesus’ name, Amen.', 'Isaiah 41:10'),
 ('pl-career-10', 'career', 10, 'Calling and purpose', 'Lord, I am Your workmanship, created in Christ Jesus for good works You prepared beforehand. Show me the gifts You have placed in me and the purpose behind my work. Help me walk faithfully in my calling, whether my role seems big or small. In Jesus’ name, Amen.', 'Ephesians 2:10'),
 ('pl-career-11', 'career', 11, 'For my colleagues', 'Father, I lift up my colleagues before You. Bless their families, ease their burdens and draw them to Yourself. Help my light shine at work through kindness, patience and good work, so they may see Your goodness and glorify You. In Jesus’ name, Amen.', 'Matthew 5:16'),
 ('pl-career-12', 'career', 12, 'Promotion with humility', 'Lord, I humble myself under Your mighty hand and trust You to lift me up in due time, rather than pushing myself forward. If You promote me, keep my heart grateful and teachable, and help me use any influence to serve others well. In Jesus’ name, Amen.', '1 Peter 5:6'),
 ('pl-finances-01', 'finances', 1, 'Daily provision', 'Father, give us this day our daily bread. You know what I need for food, transport and bills today. Help me trust You one day at a time, be grateful for what You provide and share with those who have less. In Jesus’ name, Amen.', 'Matthew 6:11'),
 ('pl-finances-02', 'finances', 2, 'Freedom from debt', 'Lord, I bring my debts to You honestly, without hiding or shame. Your Word calls me to owe no one anything but love. Give me a realistic plan to repay what I owe, self-control to stop borrowing more and grace to keep my word. In Jesus’ name, Amen.', 'Romans 13:8'),
 ('pl-finances-03', 'finances', 3, 'Wisdom with money', 'Father, teach me to be faithful with what I have, however little it seems. Help me budget, spend thoughtfully and avoid waste. Let me manage money in a way that honours You and serves the people You have given me to care for. In Jesus’ name, Amen.', 'Luke 16:10'),
 ('pl-finances-04', 'finances', 4, 'A contented heart', 'Lord, free me from the love of money and the pressure to keep up with others. Teach me to be content with what I have, because You have promised never to leave me nor forsake me. You are my true security. In Jesus’ name, Amen.', 'Hebrews 13:5'),
 ('pl-finances-05', 'finances', 5, 'A generous heart', 'Lord Jesus, You said it is more blessed to give than to receive. Give me a kind, open heart toward people in need. Show me simple ways to help, with a meal, my time or what I can spare, and let my generosity flow from love, not pressure. In Jesus’ name, Amen.', 'Acts 20:35'),
 ('pl-finances-06', 'finances', 6, 'A steady income', 'Father, I commit my work and plans to You. Where my income is uncertain, bring steadiness. Establish my plans, open reliable opportunities and help me handle both the good months and the slow ones with wisdom and peace. In Jesus’ name, Amen.', 'Proverbs 16:3'),
 ('pl-finances-07', 'finances', 7, 'Freedom from money fears', 'Father, fear about money keeps me awake and steals my peace. Your Word reminds me that You know exactly what I need. Break the grip of worry over my mind, help me take practical steps and teach me to rest in Your care as Your child. In Jesus’ name, Amen.', 'Matthew 6:31-32'),
 ('pl-finances-08', 'finances', 8, 'Honest gain', 'Lord, keep me from shortcuts, schemes and dishonest gain. Help me earn through honest labour and fair dealing. Even when others seem to get ahead by cheating, give me patience to build slowly and steadily in a way that honours You. In Jesus’ name, Amen.', 'Proverbs 13:11'),
 ('pl-finances-09', 'finances', 9, 'Planning and saving', 'Father, like the ant that gathers its food in summer, teach me to plan ahead. Help me save a little regularly, prepare for emergencies and avoid living only for today. Give me discipline without anxiety and wisdom to set good goals for my family. In Jesus’ name, Amen.', 'Proverbs 6:6-8'),
 ('pl-finances-10', 'finances', 10, 'School fees and rent', 'Father, You know the school fees and rent that are due, and the deadline feels close. You promised to supply all my needs according to Your riches in glory by Christ Jesus. Make a way where I cannot see one, and give me wisdom and favour. In Jesus’ name, Amen.', 'Philippians 4:19'),
 ('pl-finances-11', 'finances', 11, 'Blessed to bless', 'Lord, as You blessed Abraham so he could be a blessing, let whatever You give me flow through me to others. Keep me from selfishness and pride. Use my home, my skills and my resources to lift up people around me and make Your kindness known. In Jesus’ name, Amen.', 'Genesis 12:2'),
 ('pl-finances-12', 'finances', 12, 'Trust in lean seasons', 'Father, even when the fig tree does not blossom and the stalls are empty, I will rejoice in You. This season is lean, but You are still my God and my Saviour. Sustain my family, keep us from despair and help us trust You day by day. In Jesus’ name, Amen.', 'Habakkuk 3:17-18'),
 ('pl-personal-01', 'personal', 1, 'A deeper walk', 'Lord, I want more than a surface faith. You promised that as I draw near to You, You will draw near to me. Pull me closer through Your Word, prayer and worship, and help me make room in my busy days simply to be with You. In Jesus’ name, Amen.', 'James 4:8'),
 ('pl-personal-02', 'personal', 2, 'A pure heart', 'Create in me a clean heart, O God, and renew a right spirit within me. Wash away what is hidden and impure. Guard my eyes, my thoughts and my desires, and help me choose what pleases You even when no one else is watching. In Jesus’ name, Amen.', 'Psalm 51:10');
INSERT INTO prayer_library (id, category, sort, title, prayer, reference) VALUES
 ('pl-personal-03', 'personal', 3, 'Overcoming a habit', 'Father, You know the habit I keep falling back into. You promised that no temptation is beyond what I can bear and that You always make a way of escape. Help me see that way and take it. Give me honest friends, new patterns and fresh grace each time I start again. In Jesus’ name, Amen.', '1 Corinthians 10:13'),
 ('pl-personal-04', 'personal', 4, 'For patience', 'Lord, I am quick to want things now. Let patience have its perfect work in me, making me mature and complete. Help me wait well, respond gently when others frustrate me and trust that Your timing is better than mine. In Jesus’ name, Amen.', 'James 1:4'),
 ('pl-personal-05', 'personal', 5, 'For joy', 'Father, the joy of the Lord is my strength. When life feels heavy, restore the joy of knowing You. Help me notice Your goodness in small things, give thanks in every season and carry a gladness that circumstances cannot steal. In Jesus’ name, Amen.', 'Nehemiah 8:10'),
 ('pl-personal-06', 'personal', 6, 'For self-control', 'Holy Spirit, grow Your fruit in me, especially self-control. Help me govern my tongue, my appetite, my spending, my screen time and my temper. Where I have been ruled by impulse, teach me to be led by You, one wise choice at a time. In Jesus’ name, Amen.', 'Galatians 5:22-23'),
 ('pl-personal-07', 'personal', 7, 'A renewed mind', 'Lord, I do not want to be shaped by the pattern of this world. Transform me by renewing my mind. Replace lies with Your truth, fear with faith and negative thinking with hope, so I can know and follow Your good and perfect will. In Jesus’ name, Amen.', 'Romans 12:2'),
 ('pl-personal-08', 'personal', 8, 'For courage', 'Father, You told Joshua to be strong and of good courage, and promised to be with him wherever he went. Give me that same courage today. Help me face what I have been avoiding, speak truth with love and step forward in faith, knowing You are with me. In Jesus’ name, Amen.', 'Joshua 1:9'),
 ('pl-personal-09', 'personal', 9, 'For humility', 'Lord Jesus, You humbled Yourself for my sake. Free me from pride, selfish ambition and the need to be noticed. Teach me to esteem others better than myself, listen more than I speak and celebrate other people’s success without envy. In Jesus’ name, Amen.', 'Philippians 2:3'),
 ('pl-personal-10', 'personal', 10, 'Consistency in prayer', 'Father, I want prayer to be a steady part of my life, not only an emergency call. Teach me to pray always and not lose heart. Help me set aside time each day, keep talking with You through the hours and stay faithful when answers are slow. In Jesus’ name, Amen.', 'Luke 18:1'),
 ('pl-personal-11', 'personal', 11, 'Hearing God’s voice', 'Lord Jesus, You said Your sheep hear Your voice and follow You. Tune my heart to recognise You above the noise around me. Speak through Your Word, Your Spirit and wise counsel, and give me the humility and courage to obey what I hear. In Jesus’ name, Amen.', 'John 10:27'),
 ('pl-personal-12', 'personal', 12, 'More like Jesus', 'Father, as I behold Your glory, change me into the image of Jesus from glory to glory. Make me kind like Him, patient like Him and faithful like Him. Let people meet a little more of Christ in me each day. In Jesus’ name, Amen.', '2 Corinthians 3:18'),
 ('pl-people-01', 'people', 1, 'For my friends', 'Lord, thank You for my friends. Help me be a friend who loves at all times, in good seasons and hard ones. Bless each of my friends with Your presence and peace, draw them closer to You and keep our friendships honest, loyal and life-giving. In Jesus’ name, Amen.', 'Proverbs 17:17'),
 ('pl-people-02', 'people', 2, 'For the sick', 'Father, I lift up those who are sick today, at home and in hospital. Strengthen them on their sickbeds and sustain them in their weakness. Bring healing, ease their pain, guide their doctors and surround them with loving care and hope. In Jesus’ name, Amen.', 'Psalm 41:3'),
 ('pl-people-03', 'people', 3, 'For those grieving', 'Lord, You are close to the brokenhearted. I pray for everyone mourning someone they love. Hold them in their tears, comfort them in the long nights and surround them with people who will sit with them patiently. Give them hope that looks beyond the grave. In Jesus’ name, Amen.', 'Psalm 34:18'),
 ('pl-people-04', 'people', 4, 'For the lonely', 'Father, You set the lonely in families. I pray for people who feel unseen, forgotten or alone. Wrap them in Your love, bring kind people into their lives and show me who I can call, visit or invite this week. In Jesus’ name, Amen.', 'Psalm 68:6'),
 ('pl-people-05', 'people', 5, 'Blessing those who hurt me', 'Lord Jesus, You taught me to love my enemies and pray for those who mistreat me. It is hard, but I choose to obey. I bless the person who hurt me. Heal what they broke in me, work kindly in their heart and free me from bitterness and revenge. In Jesus’ name, Amen.', 'Luke 6:27-28'),
 ('pl-people-06', 'people', 6, 'For my neighbours', 'Father, bless the people who live around me. Help me love my neighbours as myself, with a greeting, a helping hand and a listening ear. Protect our street and community, meet each household’s needs and let them see Your kindness through me. In Jesus’ name, Amen.', 'Mark 12:31'),
 ('pl-people-07', 'people', 7, 'Someone far from God', 'Father, I pray for someone I love who has wandered far from You. Like the father who ran to meet his returning son, You are watching with compassion. Draw them home, soften their heart and help me love them patiently without judgment. In Jesus’ name, Amen.', 'Luke 15:20'),
 ('pl-people-08', 'people', 8, 'For my mentors', 'Lord, thank You for mentors and spiritual parents who have sharpened me as iron sharpens iron. Bless them, refresh them and reward their faithfulness. Lead me to wise people who can guide me, and make me a mentor who pours into others too. In Jesus’ name, Amen.', 'Proverbs 27:17'),
 ('pl-people-09', 'people', 9, 'The poor and hungry', 'Father, You give food to the hungry and justice to the oppressed. I pray for families who do not know where their next meal will come from. Provide for them, open doors for work and dignity, and move me to meet real needs with compassion. In Jesus’ name, Amen.', 'Psalm 146:7'),
 ('pl-people-10', 'people', 10, 'Widows and orphans', 'Lord, You are a Father to the fatherless and a defender of widows. Comfort those who have lost a spouse or parents. Protect them from those who would take advantage, meet their needs and surround them with a caring community that treats them as family. In Jesus’ name, Amen.', 'Psalm 68:5'),
 ('pl-people-11', 'people', 11, 'For prisoners', 'Father, I remember those in prison as if I were bound with them. Bring justice for the wrongly accused, repentance and new beginnings for the guilty, and hope for all. Comfort their families, bless prison chaplains and let the good news set hearts free. In Jesus’ name, Amen.', 'Hebrews 13:3'),
 ('pl-people-12', 'people', 12, 'The anxious and depressed', 'Lord, I lift up those battling anxiety and depression. When their soul is cast down, be the hope that holds them. Lift the heaviness, quiet racing thoughts and lead them to good help, including doctors and counsellors. Remind them they are deeply loved and never alone. In Jesus’ name, Amen.', 'Psalm 42:11'),
 ('pl-global-01', 'global', 1, 'Our nation and leaders', 'Father, I pray for our nation and all in authority over us. Give our leaders wisdom, integrity and a heart for the common good. Remove corruption, protect our communities and grant us peace, so that we may live quiet and godly lives. In Jesus’ name, Amen.', '1 Timothy 2:1-2'),
 ('pl-global-02', 'global', 2, 'Peace in the world', 'Prince of Peace, the world is weary of war. Hasten the day when nations beat their swords into ploughshares and learn war no more. Stop conflicts, soften hardened hearts and raise up peacemakers in every land. In Jesus’ name, Amen.', 'Isaiah 2:4'),
 ('pl-global-03', 'global', 3, 'Persecuted Christians', 'Lord, I stand with believers who suffer for Your name. When they are troubled on every side, keep them from being crushed; when persecuted, remind them they are never forsaken. Strengthen their faith, protect their families and let their courage point many to Jesus. In Jesus’ name, Amen.', '2 Corinthians 4:8-9'),
 ('pl-global-04', 'global', 4, 'Gospel to every nation', 'Lord Jesus, You sent us to make disciples of all nations, and You promised to be with us always. Carry the gospel to every people and language that has not yet heard. Bless Bible translators, evangelists and church planters, and open doors that seem closed. In Jesus’ name, Amen.', 'Matthew 28:19-20'),
 ('pl-global-05', 'global', 5, 'For justice', 'Righteous God, let justice roll down like waters and righteousness like a mighty stream. Defend the poor and oppressed, expose corruption and give courage to judges and officials who choose what is right. Help me do justice in my own small corner too. In Jesus’ name, Amen.', 'Amos 5:24'),
 ('pl-global-06', 'global', 6, 'Disaster victims', 'Father, You are our refuge and strength, a very present help in trouble. I pray for people suffering from floods, fires, earthquakes and other disasters. Comfort the grieving, shelter the displaced, strengthen rescue workers and speed help to those who need it most. In Jesus’ name, Amen.', 'Psalm 46:1'),
 ('pl-global-07', 'global', 7, 'For refugees', 'Lord, You love the stranger and provide them food and clothing. I pray for refugees and displaced people far from home. Keep them safe on dangerous journeys, reunite separated families and give them welcome, dignity and a new start. Help us love the stranger as You do. In Jesus’ name, Amen.', 'Deuteronomy 10:18-19'),
 ('pl-global-08', 'global', 8, 'Revival across Africa', 'Father, let Africa stretch out her hands to You. Send revival across our continent, from city to village. Heal our lands of division, poverty and conflict, raise up godly leaders and let a generation of Africans carry the gospel with humility and power. In Jesus’ name, Amen.', 'Psalm 68:31'),
 ('pl-global-09', 'global', 9, 'The next generation', 'Lord, pour out Your Spirit on our sons and daughters. Let the next generation know You personally, not just by tradition. Guard them from confusion and hopelessness, give them bold faith and God-given dreams, and help older believers guide them with love. In Jesus’ name, Amen.', 'Joel 2:28'),
 ('pl-global-10', 'global', 10, 'For health workers', 'Father, bless doctors, nurses, pharmacists and caregivers. You give power to the faint and strength to the weary. Refresh them through long shifts, give them skill and wisdom, protect them from harm and let them know their compassion matters. In Jesus’ name, Amen.', 'Isaiah 40:29'),
 ('pl-global-11', 'global', 11, 'An end to violence', 'Lord, I cry out for an end to violence, kidnapping and bloodshed. You promised a day when violence will no more be heard in the land. Protect the vulnerable, turn the hearts of those who harm others and comfort families who have suffered loss. In Jesus’ name, Amen.', 'Isaiah 60:18'),
 ('pl-global-12', 'global', 12, 'Wisdom for world leaders', 'Father, the hearts of kings are in Your hand. I pray for presidents, prime ministers and world leaders. Guide their decisions, give them wisdom and humility to seek the common good, and turn their hearts toward justice and peace. In Jesus’ name, Amen.', 'Proverbs 21:1');
