-- SpiritualGym: a categorised Scripture-memory library (224 KJV verses) and a guided prayer library (84 prayers)

CREATE TABLE memory_library (
  id        TEXT PRIMARY KEY,
  category  TEXT NOT NULL,
  sort      INTEGER NOT NULL DEFAULT 0,
  reference TEXT NOT NULL,
  text      TEXT NOT NULL
);
CREATE INDEX idx_memory_library ON memory_library(category, sort);

CREATE TABLE prayer_library (
  id        TEXT PRIMARY KEY,
  category  TEXT NOT NULL,
  sort      INTEGER NOT NULL DEFAULT 0,
  title     TEXT NOT NULL,
  prayer    TEXT NOT NULL,
  reference TEXT
);
CREATE INDEX idx_prayer_library ON prayer_library(category, sort);

-- Remember which library prayer an item on someone's list came from
ALTER TABLE prayer_items ADD COLUMN library_id TEXT;

